  useEffect(()=>{if(!db){setLoaded(true);return;} const client=db;let active=true;async function syncIdentity(nextUser:User|null){if(!active)return;setUser(nextUser);if(!nextUser){setRole("");setNeedsProfile(false);setRequestStatus("");setLoaded(true);return;}try{const [{data:member,error:memberError},{data:profile,error:profileError}]=await Promise.all([client.from("workspace_members").select("role").eq("workspace_id",workspaceId).eq("user_id",nextUser.id).maybeSingle(),client.from("profiles").select("first_name,last_name").eq("id",nextUser.id).maybeSingle()]);if(memberError)throw memberError;if(profileError)throw profileError;setRole(member?.role||"");setFirstName(profile?.first_name||String(nextUser.user_metadata?.first_name||""));setLastName(profile?.last_name||String(nextUser.user_metadata?.last_name||""));setNeedsProfile(!profile?.first_name?.trim()||!profile?.last_name?.trim());if(member){setRequestStatus("approved");setAdminNotified(null);}else{const response=await fetch("/api/access-requests",{method:"POST"});const result=await response.json();if(!response.ok)throw new Error(result.error||"Could not request workspace access");setRequestStatus(result.status);setAdminNotified(result.email_sent===true);}}catch(error){setRequestStatus("error");setError(error instanceof Error?error.message:"Could not load account access");}finally{if(active)setLoaded(true);}}void client.auth.getUser().then(({data:{user}})=>syncIdentity(user));const {data:{subscription}}=client.auth.onAuthStateChange((event,session)=>{if(!session){void syncIdentity(null);return;}setUser(session.user);if(event==="SIGNED_IN"){setLoaded(false);setTimeout(()=>void syncIdentity(session.user),0);}});return()=>{active=false;subscription.unsubscribe();};},[]);
