  async function sendMagicLink(){if(!db||authBusy)return;setError("");setNotice("");setAuthBusy(true);try{const {error}=await db.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:location.origin,shouldCreateUser:true}});if(error)throw error;setNotice("Check your email for a sign-in link. If this is your first time here, you’ll add your name after signing in and request workspace access.");}catch(error){setError(error instanceof Error?error.message:"Could not send a sign-in link");}finally{setAuthBusy(false);}}
