  async function saveProfile(first:string,last:string){if(!db||!user)return;setError("");const first_name=first.trim(),last_name=last.trim();const {error}=await db.from("profiles").update({first_name,last_name,display_name:`${first_name} ${last_name}`}).eq("id",user.id);if(error){setError(error.message);return;}const {error:metadataError}=await db.auth.updateUser({data:{first_name,last_name,full_name:`${first_name} ${last_name}`}});if(metadataError){setError(metadataError.message);return;}if(!role){const response=await fetch("/api/access-requests",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({first_name,last_name})});const result=await response.json();if(!response.ok){setError(result.error||"Name saved, but it could not be added to the access request. Try again.");return;}location.reload();return;}setNeedsProfile(false);setNotice("Profile saved. Teammates can now assign work to you by name.");await load();}
  async function enrollPasskey(){if(!db)return;setError("");setNotice("");setAuthBusy(true);try{const {error}=await db.auth.registerPasskey();if(error)throw error;setNotice("Passkey added to your account.");}catch(error){setError(error instanceof Error?error.message:"Could not add a passkey");}finally{setAuthBusy(false);}}
  async function save(table:string,record:Item,success="Saved"){if(!db||!canEdit)return;setError("");const {error}=await saveWorkspaceRecord(db,table,record,workspaceId);if(error){setError(error.message);return;}setNotice(success);await load();}
  async function saveNote(record:Record<string,unknown>):Promise<boolean>{if(!db||!canEdit)return false;setError("");try{const {error}=await saveWorkspaceRecord(db,"record_notes",record,workspaceId);if(error)throw error;setNotice(record.id?"Note updated":"Note added");await load();return true;}catch(cause){setError(cause instanceof Error?cause.message:"Could not save note");return false;}}
  async function deleteNote(noteId:string):Promise<boolean>{if(!db||!canEdit)return false;setError("");try{const {error}=await db.from("record_notes").delete().eq("id",noteId).eq("workspace_id",workspaceId);if(error)throw error;setNotice("Note deleted");await load();return true;}catch(cause){setError(cause instanceof Error?cause.message:"Could not delete note");return false;}}
  const vendorById=useMemo(()=>new Map(data.vendors.map(v=>[v.id,v])),[data.vendors]);
  const robotById=useMemo(()=>new Map(data.robots.map(r=>[r.id,r])),[data.robots]);
