  const filteredVendors=data.vendors.filter(v=>(!search||v.name.toLowerCase().includes(search.toLowerCase()))&&(!country||v.iso_country_code===country)&&(!state||(state==="Unknown"?!v.us_state_code:v.us_state_code===state)));
