  if(needsProfile)return <div className="auth card"><div className="brand"><span className="brand-icon">R</span> RMAIIG Robots</div><h1>Set up your profile</h1><p className="muted">Add your first and last name so your workspace access request and future assignments use the right name.</p>{error&&<div className="notice error" role="alert">{error}</div>}<label className="field">First name<input className="input" autoComplete="given-name" required value={firstName} onChange={e=>setFirstName(e.target.value)}/></label><label className="field">Last name<input className="input" autoComplete="family-name" required value={lastName} onChange={e=>setLastName(e.target.value)}/></label><button className="button primary" disabled={!firstName.trim()||!lastName.trim()} onClick={()=>saveProfile(firstName,lastName)}>Save name and continue</button><button className="button" onClick={()=>db.auth.signOut()}>Sign out</button></div>;
  if(!role)return <div className="auth card"><div className="brand"><span className="brand-icon">R</span> RMAIIG Robots</div><h1>{requestStatus==="denied"?"Access request denied":"Awaiting workspace access"}</h1><p className="muted">{requestStatus==="denied"?"An administrator denied this request. Contact an administrator if you believe this was a mistake.":requestStatus==="error"?"We could not record your request. Retry to notify the administrator.":"Your request is recorded. An administrator will review it and approve or deny access."}</p>{adminNotified===true&&<p className="notice">The administrator has been notified by email.</p>}{adminNotified===false&&<p className="notice error">The request is visible in Administration, but its email alert could not be sent. The workspace email notification provider is not configured or returned an error.</p>}{requestStatus==="error"&&<button className="button primary" onClick={async()=>{setError("");const response=await fetch("/api/access-requests",{method:"POST"});const result=await response.json();if(!response.ok)setError(result.error||"Could not retry the request");else{setRequestStatus(result.status);setAdminNotified(result.email_sent===true);}}}>Retry access request</button>}{requestStatus==="pending"&&<button className="button" onClick={()=>location.reload()}>Check access status</button>}<button className="button" onClick={()=>db.auth.signOut()}>Sign out</button></div>;
