function ContactForm({vendorId,onSave}:{vendorId:string;onSave:(record:Item)=>void}){const [name,setName]=useState(""),[email,setEmail]=useState(""),[title,setTitle]=useState(""),[url,setUrl]=useState("");return <form className="stack" onSubmit={e=>{e.preventDefault();onSave({workspace_id:workspaceId,vendor_id:vendorId,name:name||null,business_email:email||null,job_title:title||null,contact_form_url:url||null,email_status:email?"unverified":"unknown"});setName("");setEmail("");setTitle("");setUrl("");}}><h3>Add professional contact</h3><input className="input" placeholder="Name" aria-label="Contact name" value={name} onChange={e=>setName(e.target.value)}/><input className="input" placeholder="Job title" aria-label="Job title" value={title} onChange={e=>setTitle(e.target.value)}/><input className="input" type="email" placeholder="Business email" aria-label="Business email" value={email} onChange={e=>setEmail(e.target.value)}/><input className="input" type="url" placeholder="Contact form URL" aria-label="Contact form URL" value={url} onChange={e=>setUrl(e.target.value)}/><button className="button">Add contact</button></form>;}
